        "content": "/**\n * Bun utility script that validates JSON input from stdin.\n * Exits with code 0 for valid JSON, 1 for invalid JSON.\n */\n\nconst input = await Bun.stdin.text();\n\nif (input.trim().length === 0) {\n  console.error(\"Error: No input provided. Please pipe JSON to stdin.\");\n  process.exit(1);\n}\n\ntry {\n  const parsed = JSON.parse(input);\n  console.log(\"Valid JSON:\");\n  console.log(JSON.stringify(parsed, null, 2));\n  process.exit(0);\n} catch (error) {\n  const message = error instanceof SyntaxError ? error.message : \"Unknown parse error\";\n  console.error(`Invalid JSON: ${message}`);\n  process.exit(1);\n}\n"
