/**
 * Bun utility script that validates JSON input from stdin.
 * Exits with code 0 for valid JSON, 1 for invalid JSON.
 */

const input = await Bun.stdin.text();

if (input.trim().length === 0) {
  console.error("Error: No input provided. Please pipe JSON to stdin.");
  process.exit(1);
}

try {
  const parsed = JSON.parse(input);
  console.log("Valid JSON:");
  console.log(JSON.stringify(parsed, null, 2));
  process.exit(0);
} catch (error) {
  const message = error instanceof SyntaxError ? error.message : "Unknown parse error";
  console.error(`Invalid JSON: ${message}`);
  process.exit(1);
}

import { describe, expect, test } from "bun:test";
import { join } from "path";

const scriptPath = join(import.meta.dir, "validate-json.ts");

async function runValidator(input: string): Promise<{ stdout: string; stderr: string; exitCode: number }> {
  const proc = Bun.spawn(["bun", "run", scriptPath], {
    stdin: new Response(input).body!,
    stdout: "pipe",
    stderr: "pipe",
  });

  const [stdout, stderr] = await Promise.all([
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
  ]);
  const exitCode = await proc.exited;

  return { stdout, stderr, exitCode };
}

describe("validate-json", () => {
  test("valid JSON object exits with 0 and prints parsed output", async () => {
    const result = await runValidator('{"name":"test","value":42}');
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("Valid JSON:");
    expect(result.stdout).toContain('"name": "test"');
  });

  test("valid JSON array exits with 0", async () => {
    const result = await runValidator('[1, 2, 3]');
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("Valid JSON:");
  });

  test("invalid JSON exits with 1 and prints error", async () => {
    const result = await runValidator("{not valid json}");
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain("Invalid JSON:");
  });

  test("empty input exits with 1 and prints error", async () => {
    const result = await runValidator("");
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain("No input provided");
  });

  test("whitespace-only input exits with 1 and prints error", async () => {
    const result = await runValidator("   \n  ");
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain("No input provided");
  });
});

