        "old_string": "/**\n * Add two numbers.\n */\nexport function add(a: number, b: number): number {\n  return a + b;\n}",
        "new_string": "/**\n * Create a personalized greeting with a custom salutation.\n *\n * @param salutation - The greeting word or phrase (e.g., \"Hi\", \"Good morning\")\n * @param name - The name of the person to greet\n * @returns A formatted greeting string\n */\nexport function personalGreet(salutation: string, name: string): string {\n  const trimmedSalutation = salutation.trim();\n  const trimmedName = name.trim();\n\n  if (!trimmedSalutation || !trimmedName) {\n    return \"Hello!\";\n  }\n\n  return `${trimmedSalutation}, ${trimmedName}!`;\n}\n\n/**\n * Add two numbers.\n */\nexport function add(a: number, b: number): number {\n  return a + b;\n}"
