import { describe, expect, test } from "bun:test";
import { greet, add, personalGreet } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("personalGreet", () => {
  test("returns greeting with custom salutation", () => {
    expect(personalGreet("Hi", "Alice")).toBe("Hi, Alice!");
  });

  test("returns greeting with multi-word salutation", () => {
    expect(personalGreet("Good morning", "Bob")).toBe("Good morning, Bob!");
  });

  test("trims whitespace from salutation and name", () => {
    expect(personalGreet("  Hey  ", "  Carol  ")).toBe("Hey, Carol!");
  });

  test("returns fallback when salutation is empty", () => {
    expect(personalGreet("", "Alice")).toBe("Hello!");
  });

  test("returns fallback when name is empty", () => {
    expect(personalGreet("Hi", "")).toBe("Hello!");
  });

  test("returns fallback when both are whitespace-only", () => {
    expect(personalGreet("   ", "   ")).toBe("Hello!");
  });
});

