    expect(personalGreet("  Hey  ", "  Carol  ")).toBe("Hey, Carol!");
  });

  test("returns fallback when salutation is empty", () => {
    expect(personalGreet("", "Alice")).toBe("Hello!");
  });

  test("returns fallback when name is empty", () => {
    expect(personalGreet("Hi", "")).toBe("Hello!");
  });

  test("returns fallback when both are whitespace-only", () => {
    expect(personalGreet("   ", "   ")).toBe("Hello!");
  });
});

