        "content": "/**\n * High-performance JSON validation module.\n *\n * Uses a compile-once, validate-many pattern: a schema is compiled into\n * a reusable validation function that avoids repeated schema traversal.\n */\n\nexport type SchemaType = \"string\" | \"number\" | \"boolean\" | \"object\" | \"array\";\n\nexport interface SchemaProperty {\n  type: SchemaType;\n  properties?: Record<string, SchemaProperty>;\n  required?: string[];\n  items?: SchemaProperty;\n}\n\nexport interface ValidationError {\n  path: string;\n  message: string;\n}\n\nexport interface ValidationResult {\n  valid: boolean;\n  errors: ValidationError[];\n}\n\nconst EMPTY_ERRORS: readonly ValidationError[] = Object.freeze([]);\nconst VALID_RESULT: ValidationResult = Object.freeze({\n  valid: true,\n  errors: EMPTY_ERRORS as ValidationError[],\n});\n\ntype ValidatorFn = (data: unknown) => ValidationResult;\n\ninterface CompiledNode {\n  type: SchemaType;\n  requiredSet: Set<string> | null;\n  propertyKeys: string[] | null;\n  propertyValidators: Map<string, CompiledNode> | null;\n  itemsNode: CompiledNode | null;\n}\n\nfunction compileNode(schema: SchemaProperty): CompiledNode {\n  let requiredSet: Set<string> | null = null;\n  let propertyKeys: string[] | null = null;\n  let propertyValidators: Map<string, CompiledNode> | null = null;\n  let itemsNode: CompiledNode | null = null;\n\n  if (schema.type === \"object\" && schema.properties) {\n    propertyKeys = Object.keys(schema.properties);\n    propertyValidators = new Map();\n    for (let i = 0; i < propertyKeys.length; i++) {\n      const key = propertyKeys[i];\n      propertyValidators.set(key, compileNode(schema.properties[key]));\n    }\n    if (schema.required && schema.required.length > 0) {\n      requiredSet = new Set(schema.required);\n    }\n  }\n\n  if (schema.type === \"array\" && schema.items) {\n    itemsNode = compileNode(schema.items);\n  }\n\n  return { type: schema.type, requiredSet, propertyKeys, propertyValidators, itemsNode };\n}\n\nfunction validateNode(\n  node: CompiledNode,\n  data: unknown,\n  path: string,\n  errors: ValidationError[],\n): void {\n  if (data === null || data === undefined) {\n    errors.push({ path, message: `Expected ${node.type}, got ${data === null ? \"null\" : \"undefined\"}` });\n    return;\n  }\n\n  switch (node.type) {\n    case \"string\":\n      if (typeof data !== \"string\") {\n        errors.push({ path, message: `Expected string, got ${typeof data}` });\n      }\n      return;\n\n    case \"number\":\n      if (typeof data !== \"number\") {\n        errors.push({ path, message: `Expected number, got ${typeof data}` });\n      }\n      return;\n\n    case \"boolean\":\n      if (typeof data !== \"boolean\") {\n        errors.push({ path, message: `Expected boolean, got ${typeof data}` });\n      }\n      return;\n\n    case \"array\": {\n      if (!Array.isArray(data)) {\n        errors.push({ path, message: `Expected array, got ${typeof data}` });\n        return;\n      }\n      if (node.itemsNode) {\n        for (let i = 0; i < data.length; i++) {\n          validateNode(node.itemsNode, data[i], `${path}[${i}]`, errors);\n        }\n      }\n      return;\n    }\n\n    case \"object\": {\n      if (typeof data !== \"object\" || Array.isArray(data)) {\n        errors.push({ path, message: `Expected object, got ${Array.isArray(data) ? \"array\" : typeof data}` });\n        return;\n      }\n\n      const obj = data as Record<string, unknown>;\n\n      if (node.requiredSet) {\n        for (const key of node.requiredSet) {\n          if (!(key in obj)) {\n            errors.push({ path: path ? `${path}.${key}` : key, message: \"Required field missing\" });\n          }\n        }\n      }\n\n      if (node.propertyValidators && node.propertyKeys) {\n        for (let i = 0; i < node.propertyKeys.length; i++) {\n          const key = node.propertyKeys[i];\n          if (key in obj) {\n            const childNode = node.propertyValidators.get(key)!;\n            validateNode(childNode, obj[key], path ? `${path}.${key}` : key, errors);\n          }\n        }\n      }\n      return;\n    }\n  }\n}\n\n/**\n * Compile a schema into a reusable validation function.\n *\n * The returned function validates data against the schema without\n * re-traversing the schema definition on each call.\n */\nexport function compileValidator(schema: SchemaProperty): ValidatorFn {\n  const root = compileNode(schema);\n\n  return (data: unknown): ValidationResult => {\n    const errors: ValidationError[] = [];\n    validateNode(root, data, \"\", errors);\n\n    if (errors.length === 0) {\n      return VALID_RESULT;\n    }\n\n    return { valid: false, errors };\n  };\n}\n"
