        "content": "import { describe, expect, test } from \"bun:test\";\nimport { compileValidator, type SchemaProperty } from \"./validate-json\";\n\nconst userSchema: SchemaProperty = {\n  type: \"object\",\n  required: [\"name\", \"age\"],\n  properties: {\n    name: { type: \"string\" },\n    age: { type: \"number\" },\n    active: { type: \"boolean\" },\n  },\n};\n\nconst nestedSchema: SchemaProperty = {\n  type: \"object\",\n  required: [\"user\"],\n  properties: {\n    user: {\n      type: \"object\",\n      required: [\"email\"],\n      properties: {\n        email: { type: \"string\" },\n        profile: {\n          type: \"object\",\n          properties: {\n            bio: { type: \"string\" },\n          },\n        },\n      },\n    },\n  },\n};\n\nconst arraySchema: SchemaProperty = {\n  type: \"object\",\n  required: [\"tags\"],\n  properties: {\n    tags: {\n      type: \"array\",\n      items: { type: \"string\" },\n    },\n    scores: {\n      type: \"array\",\n      items: { type: \"number\" },\n    },\n  },\n};\n\ndescribe(\"validate-json\", () => {\n  describe(\"valid payloads\", () => {\n    test(\"accepts a fully valid object\", () => {\n      const validate = compileValidator(userSchema);\n      const result = validate({ name: \"Alice\", age: 30, active: true });\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"accepts an object with only required fields\", () => {\n      const validate = compileValidator(userSchema);\n      const result = validate({ name: \"Bob\", age: 25 });\n      expect(result.valid).toBe(true);\n    });\n  });\n\n  describe(\"missing required fields\", () => {\n    test(\"rejects when a required field is missing\", () => {\n      const validate = compileValidator(userSchema);\n      const result = validate({ name: \"Alice\" });\n      expect(result.valid).toBe(false);\n      expect(result.errors).toHaveLength(1);\n      expect(result.errors[0].path).toBe(\"age\");\n      expect(result.errors[0].message).toBe(\"Required field missing\");\n    });\n\n    test(\"reports multiple missing required fields\", () => {\n      const validate = compileValidator(userSchema);\n      const result = validate({});\n      expect(result.valid).toBe(false);\n      expect(result.errors).toHaveLength(2);\n    });\n  });\n\n  describe(\"wrong types\", () => {\n    test(\"rejects when a field has the wrong type\", () => {\n      const validate = compileValidator(userSchema);\n      const result = validate({ name: 123, age: 30 });\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].path).toBe(\"name\");\n      expect(result.errors[0].message).toBe(\"Expected string, got number\");\n    });\n\n    test(\"rejects number where string expected\", () => {\n      const validate = compileValidator({ type: \"string\" });\n      const result = validate(42);\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"rejects string where number expected\", () => {\n      const validate = compileValidator({ type: \"number\" });\n      const result = validate(\"hello\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"rejects string where boolean expected\", () => {\n      const validate = compileValidator({ type: \"boolean\" });\n      const result = validate(\"true\");\n      expect(result.valid).toBe(false);\n    });\n  });\n\n  describe(\"nested object validation\", () => {\n    test(\"validates nested objects\", () => {\n      const validate = compileValidator(nestedSchema);\n      const result = validate({\n        user: { email: \"a@b.com\", profile: { bio: \"hello\" } },\n      });\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"rejects missing nested required field\", () => {\n      const validate = compileValidator(nestedSchema);\n      const result = validate({ user: {} });\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].path).toBe(\"user.email\");\n    });\n\n    test(\"rejects wrong type in nested object\", () => {\n      const validate = compileValidator(nestedSchema);\n      const result = validate({ user: { email: 123 } });\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].path).toBe(\"user.email\");\n    });\n  });\n\n  describe(\"array validation\", () => {\n    test(\"validates arrays with correct item types\", () => {\n      const validate = compileValidator(arraySchema);\n      const result = validate({ tags: [\"a\", \"b\"], scores: [1, 2] });\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"rejects array items with wrong type\", () => {\n      const validate = compileValidator(arraySchema);\n      const result = validate({ tags: [\"a\", 123], scores: [1] });\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].path).toBe(\"tags[1]\");\n    });\n\n    test(\"accepts empty arrays\", () => {\n      const validate = compileValidator(arraySchema);\n      const result = validate({ tags: [], scores: [] });\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"rejects non-array where array expected\", () => {\n      const validate = compileValidator(arraySchema);\n      const result = validate({ tags: \"not-an-array\" });\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].message).toContain(\"Expected array\");\n    });\n  });\n\n  describe(\"edge cases\", () => {\n    test(\"rejects null\", () => {\n      const validate = compileValidator(userSchema);\n      const result = validate(null);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].message).toContain(\"null\");\n    });\n\n    test(\"rejects undefined\", () => {\n      const validate = compileValidator(userSchema);\n      const result = validate(undefined);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].message).toContain(\"undefined\");\n    });\n\n    test(\"validates empty object against schema with no required fields\", () => {\n      const schema: SchemaProperty = {\n        type: \"object\",\n        properties: { name: { type: \"string\" } },\n      };\n      const validate = compileValidator(schema);\n      const result = validate({});\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"rejects an array where object expected\", () => {\n      const validate = compileValidator(userSchema);\n      const result = validate([1, 2, 3]);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].message).toContain(\"Expected object\");\n    });\n  });\n\n  describe(\"performance\", () => {\n    test(\"validates 100k objects under 500ms\", () => {\n      const validate = compileValidator(userSchema);\n      const payload = { name: \"Alice\", age: 30, active: true };\n\n      const start = performance.now();\n      for (let i = 0; i < 100_000; i++) {\n        validate(payload);\n      }\n      const elapsed = performance.now() - start;\n\n      expect(elapsed).toBeLessThan(500);\n    });\n  });\n});\n"
      },
