/**
 * High-performance JSON validation module.
 *
 * Uses a compile-once, validate-many pattern: a schema is compiled into
 * a reusable validation function that avoids repeated schema traversal.
 */

export type SchemaType = "string" | "number" | "boolean" | "object" | "array";

export interface SchemaProperty {
  type: SchemaType;
  properties?: Record<string, SchemaProperty>;
  required?: string[];
  items?: SchemaProperty;
}

export interface ValidationError {
  path: string;
  message: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

const EMPTY_ERRORS: readonly ValidationError[] = Object.freeze([]);
const VALID_RESULT: ValidationResult = Object.freeze({
  valid: true,
  errors: EMPTY_ERRORS as ValidationError[],
});

type ValidatorFn = (data: unknown) => ValidationResult;

interface CompiledNode {
  type: SchemaType;
  requiredSet: Set<string> | null;
  propertyKeys: string[] | null;
  propertyValidators: Map<string, CompiledNode> | null;
  itemsNode: CompiledNode | null;
}

function compileNode(schema: SchemaProperty): CompiledNode {
  let requiredSet: Set<string> | null = null;
  let propertyKeys: string[] | null = null;
  let propertyValidators: Map<string, CompiledNode> | null = null;
  let itemsNode: CompiledNode | null = null;

  if (schema.type === "object" && schema.properties) {
    propertyKeys = Object.keys(schema.properties);
    propertyValidators = new Map();
    for (let i = 0; i < propertyKeys.length; i++) {
      const key = propertyKeys[i];
      propertyValidators.set(key, compileNode(schema.properties[key]));
    }
    if (schema.required && schema.required.length > 0) {
      requiredSet = new Set(schema.required);
    }
  }

  if (schema.type === "array" && schema.items) {
    itemsNode = compileNode(schema.items);
  }

  return { type: schema.type, requiredSet, propertyKeys, propertyValidators, itemsNode };
}

function validateNode(
  node: CompiledNode,
  data: unknown,
  path: string,
  errors: ValidationError[],
): void {
  if (data === null || data === undefined) {
    errors.push({ path, message: `Expected ${node.type}, got ${data === null ? "null" : "undefined"}` });
    return;
  }

  switch (node.type) {
    case "string":
      if (typeof data !== "string") {
        errors.push({ path, message: `Expected string, got ${typeof data}` });
      }
      return;

    case "number":
      if (typeof data !== "number") {
        errors.push({ path, message: `Expected number, got ${typeof data}` });
      }
      return;

    case "boolean":
      if (typeof data !== "boolean") {
        errors.push({ path, message: `Expected boolean, got ${typeof data}` });
      }
      return;

    case "array": {
      if (!Array.isArray(data)) {
        errors.push({ path, message: `Expected array, got ${typeof data}` });
        return;
      }
      if (node.itemsNode) {
        for (let i = 0; i < data.length; i++) {
          validateNode(node.itemsNode, data[i], `${path}[${i}]`, errors);
        }
      }
      return;
    }

    case "object": {
      if (typeof data !== "object" || Array.isArray(data)) {
        errors.push({ path, message: `Expected object, got ${Array.isArray(data) ? "array" : typeof data}` });
        return;
      }

      const obj = data as Record<string, unknown>;

      if (node.requiredSet) {
        for (const key of node.requiredSet) {
          if (!(key in obj)) {
            errors.push({ path: path ? `${path}.${key}` : key, message: "Required field missing" });
          }
        }
      }

      if (node.propertyValidators && node.propertyKeys) {
        for (let i = 0; i < node.propertyKeys.length; i++) {
          const key = node.propertyKeys[i];
          if (key in obj) {
            const childNode = node.propertyValidators.get(key)!;
            validateNode(childNode, obj[key], path ? `${path}.${key}` : key, errors);
          }
        }
      }
      return;
    }
  }
}

/**
 * Compile a schema into a reusable validation function.
 *
 * The returned function validates data against the schema without
 * re-traversing the schema definition on each call.
 */
export function compileValidator(schema: SchemaProperty): ValidatorFn {
  const root = compileNode(schema);

  return (data: unknown): ValidationResult => {
    const errors: ValidationError[] = [];
    validateNode(root, data, "", errors);

    if (errors.length === 0) {
      return VALID_RESULT;
    }

    return { valid: false, errors };
  };
}

import { describe, expect, test } from "bun:test";
import { compileValidator, type SchemaProperty } from "./validate-json";

const userSchema: SchemaProperty = {
  type: "object",
  required: ["name", "age"],
  properties: {
    name: { type: "string" },
    age: { type: "number" },
    active: { type: "boolean" },
  },
};

const nestedSchema: SchemaProperty = {
  type: "object",
  required: ["user"],
  properties: {
    user: {
      type: "object",
      required: ["email"],
      properties: {
        email: { type: "string" },
        profile: {
          type: "object",
          properties: {
            bio: { type: "string" },
          },
        },
      },
    },
  },
};

const arraySchema: SchemaProperty = {
  type: "object",
  required: ["tags"],
  properties: {
    tags: {
      type: "array",
      items: { type: "string" },
    },
    scores: {
      type: "array",
      items: { type: "number" },
    },
  },
};

describe("validate-json", () => {
  describe("valid payloads", () => {
    test("accepts a fully valid object", () => {
      const validate = compileValidator(userSchema);
      const result = validate({ name: "Alice", age: 30, active: true });
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts an object with only required fields", () => {
      const validate = compileValidator(userSchema);
      const result = validate({ name: "Bob", age: 25 });
      expect(result.valid).toBe(true);
    });
  });

  describe("missing required fields", () => {
    test("rejects when a required field is missing", () => {
      const validate = compileValidator(userSchema);
      const result = validate({ name: "Alice" });
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].path).toBe("age");
      expect(result.errors[0].message).toBe("Required field missing");
    });

    test("reports multiple missing required fields", () => {
      const validate = compileValidator(userSchema);
      const result = validate({});
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(2);
    });
  });

  describe("wrong types", () => {
    test("rejects when a field has the wrong type", () => {
      const validate = compileValidator(userSchema);
      const result = validate({ name: 123, age: 30 });
      expect(result.valid).toBe(false);
      expect(result.errors[0].path).toBe("name");
      expect(result.errors[0].message).toBe("Expected string, got number");
    });

    test("rejects number where string expected", () => {
      const validate = compileValidator({ type: "string" });
      const result = validate(42);
      expect(result.valid).toBe(false);
    });

    test("rejects string where number expected", () => {
      const validate = compileValidator({ type: "number" });
      const result = validate("hello");
      expect(result.valid).toBe(false);
    });

    test("rejects string where boolean expected", () => {
      const validate = compileValidator({ type: "boolean" });
      const result = validate("true");
      expect(result.valid).toBe(false);
    });
  });

  describe("nested object validation", () => {
    test("validates nested objects", () => {
      const validate = compileValidator(nestedSchema);
      const result = validate({
        user: { email: "a@b.com", profile: { bio: "hello" } },
      });
      expect(result.valid).toBe(true);
    });

    test("rejects missing nested required field", () => {
      const validate = compileValidator(nestedSchema);
      const result = validate({ user: {} });
      expect(result.valid).toBe(false);
      expect(result.errors[0].path).toBe("user.email");
    });

    test("rejects wrong type in nested object", () => {
      const validate = compileValidator(nestedSchema);
      const result = validate({ user: { email: 123 } });
      expect(result.valid).toBe(false);
      expect(result.errors[0].path).toBe("user.email");
    });
  });

  describe("array validation", () => {
    test("validates arrays with correct item types", () => {
      const validate = compileValidator(arraySchema);
      const result = validate({ tags: ["a", "b"], scores: [1, 2] });
      expect(result.valid).toBe(true);
    });

    test("rejects array items with wrong type", () => {
      const validate = compileValidator(arraySchema);
      const result = validate({ tags: ["a", 123], scores: [1] });
      expect(result.valid).toBe(false);
      expect(result.errors[0].path).toBe("tags[1]");
    });

    test("accepts empty arrays", () => {
      const validate = compileValidator(arraySchema);
      const result = validate({ tags: [], scores: [] });
      expect(result.valid).toBe(true);
    });

    test("rejects non-array where array expected", () => {
      const validate = compileValidator(arraySchema);
      const result = validate({ tags: "not-an-array" });
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("Expected array");
    });
  });

  describe("edge cases", () => {
    test("rejects null", () => {
      const validate = compileValidator(userSchema);
      const result = validate(null);
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("null");
    });

    test("rejects undefined", () => {
      const validate = compileValidator(userSchema);
      const result = validate(undefined);
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("undefined");
    });

    test("validates empty object against schema with no required fields", () => {
      const schema: SchemaProperty = {
        type: "object",
        properties: { name: { type: "string" } },
      };
      const validate = compileValidator(schema);
      const result = validate({});
      expect(result.valid).toBe(true);
    });

    test("rejects an array where object expected", () => {
      const validate = compileValidator(userSchema);
      const result = validate([1, 2, 3]);
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("Expected object");
    });
  });

  describe("performance", () => {
    test("validates 100k objects under 500ms", () => {
      const validate = compileValidator(userSchema);
      const payload = { name: "Alice", age: 30, active: true };

      const start = performance.now();
      for (let i = 0; i < 100_000; i++) {
        validate(payload);
      }
      const elapsed = performance.now() - start;

      expect(elapsed).toBeLessThan(500);
    });
  });
});

