/**
 * CLI entry for JSON validation.
 *
 * Usage: bun run validate <schema.json> <data.json>
 */

import { readFileSync } from "fs";
import { compileValidator, type SchemaProperty } from "./validate-json";

const args = process.argv.slice(2);

if (args.length < 2) {
  console.error("Usage: bun run validate <schema.json> <data.json>");
  process.exit(1);
}

const [schemaPath, dataPath] = args;

const schema: SchemaProperty = JSON.parse(readFileSync(schemaPath, "utf-8"));
const data: unknown = JSON.parse(readFileSync(dataPath, "utf-8"));

const validate = compileValidator(schema);
const result = validate(data);

if (result.valid) {
  console.log("Valid");
} else {
  console.error("Validation failed:");
  for (const error of result.errors) {
    console.error(`  ${error.path || "(root)"}: ${error.message}`);
  }
  process.exit(1);
}

